-- LUMIÈRE Hair Salon — sample content (idempotent, safe to re-run)

INSERT OR IGNORE INTO services (id, slug, name, category, short_description, description, price, duration, image, featured, active, sort_order) VALUES
(1, 'signature-cut-style', 'Cut & Style', 'Cuts', 'Precision cuts and styling that complement you.', 'A consultation-led cut shaped to your hair texture, face shape and daily routine. Includes a scalp-soothing cleanse, precision cut, and a finished blow-dry with our signature soft movement.', 95, 60, 'https://images.unsplash.com/photo-1595476108010-b4d1f102b1b1?auto=format&fit=crop&w=900&q=80', 1, 1, 1),
(2, 'dimensional-color', 'Color Services', 'Color', 'Beautiful, dimensional color tailored to you.', 'From a quiet gloss to hand-painted balayage, our colorists build tone in layers so grow-out stays gracious. Every service ends with a bond-repair rinse and a shine seal.', 180, 120, 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=900&q=80', 1, 1, 2),
(3, 'restorative-treatment', 'Hair Treatments', 'Treatments', 'Nourishing treatments for strong, healthy hair.', 'A diagnostic scalp and strand reading, then a bespoke mask of plant ceramides, peptides and cold-pressed oils steamed under low heat. Ideal before a color or event.', 75, 45, 'https://images.unsplash.com/photo-1580618672591-eb180b1a973f?auto=format&fit=crop&w=900&q=80', 1, 1, 3),
(4, 'hand-tied-extensions', 'Extensions', 'Extensions', 'Add length, volume and confidence instantly.', 'Hand-tied, color-matched extensions applied in fine rows for natural movement. Includes a fitting consultation, blending cut, and a home-care lesson.', 320, 150, 'https://images.unsplash.com/photo-1503104834685-7205e8607eb9?auto=format&fit=crop&w=900&q=80', 1, 1, 4),
(5, 'bridal-styling', 'Bridal Styling', 'Bridal', 'Soft, lasting styling for your wedding day.', 'A trial, a mood-board and a morning-of styling session. We build a style that holds through tears, dancing and a coastal breeze, with pins your photographer will thank us for.', 240, 90, 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=900&q=80', 0, 1, 5),
(6, 'keratin-smoothing', 'Keratin Smoothing', 'Treatments', 'Glass-smooth finish without the flat.', 'A formaldehyde-free smoothing service that softens frizz for up to twelve weeks while keeping body. Includes aftercare kit and a four-week check-in.', 210, 120, 'https://images.unsplash.com/photo-1492106087820-71f1a00d2b11?auto=format&fit=crop&w=900&q=80', 0, 1, 6),
(7, 'scalp-ritual', 'Scalp Ritual', 'Treatments', 'A slow, restorative reset for your scalp.', 'Fifteen minutes of pressure-point massage with rosemary and amla oil, a clarifying wash and a cool rinse. The most requested add-on at the salon.', 55, 30, 'https://images.unsplash.com/photo-1521590832167-7bcbfaa6381f?auto=format&fit=crop&w=900&q=80', 0, 1, 7),
(8, 'gloss-and-go', 'Gloss & Go', 'Color', 'Tone refresh in under an hour.', 'A clear or tinted gloss that mutes brass and lifts shine, finished with a five-minute blow-dry. Perfect between color appointments or before an evening out.', 85, 45, 'https://images.unsplash.com/photo-1562322140-8baeececf3df?auto=format&fit=crop&w=900&q=80', 0, 1, 8);

INSERT OR IGNORE INTO stylists (id, name, role, bio, photo, specialties, working_days, start_time, end_time, active, sort_order) VALUES
(1, 'Amara Laurent', 'Founder & Creative Director', 'Amara trained in Paris and opened LUMIÈRE in 2014 with one chair and a simple idea: healthy hair first, everything else follows. She is known for soft, face-framing shapes.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=700&q=80', 'Precision cuts, French bobs, editorial styling', '1,2,3,4,5', '10:00', '18:00', 1, 1),
(2, 'Naomi Okada', 'Master Colorist', 'Naomi paints color like watercolor — layered, translucent and built to grow out gracefully. She has spent eleven years perfecting balayage for dark hair.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=700&q=80', 'Balayage, dimensional brunette, color correction', '1,2,4,5,6', '10:00', '19:00', 1, 2),
(3, 'Sofia Marchetti', 'Senior Stylist', 'Sofia is our curl specialist and the calmest hands in the building. She builds shape with dry cutting and teaches every client how to keep it at home.', 'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=700&q=80', 'Curly cutting, blowouts, extensions', '2,3,4,5,6', '09:00', '17:00', 1, 3),
(4, 'Ines Haddad', 'Treatment & Bridal Specialist', 'Ines looks after scalp health and wedding mornings. Her braided, low-slung styles photograph beautifully and survive a full day of celebration.', 'https://images.unsplash.com/photo-1503104834685-7205e8607eb9?auto=format&fit=crop&w=700&q=80', 'Scalp therapy, bridal styling, updos', '0,1,3,5,6', '10:00', '18:00', 1, 4);

