INSERT OR IGNORE INTO testimonials (id, name, rating, text, photo, approved, created_at) VALUES
(1, 'Priya R.', 5, 'I have never had a cut grow out this well. Six weeks later it still falls into place with five minutes of air-drying. Worth every mile of the drive.', 'https://images.unsplash.com/photo-1503104834685-7205e8607eb9?auto=format&fit=crop&w=200&q=80', 1, '2026-09-14 10:00:00'),
(2, 'Camille D.', 5, 'Naomi fixed a box-dye disaster and made it look intentional. The tone is still gorgeous three months on, and she explained every step without once making me feel silly.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=80', 1, '2026-09-02 16:30:00'),
(3, 'Grace T.', 5, 'The scalp ritual is the best thirty minutes of my month. I book it the way other people book a massage. The room smells like rosemary and the tea is always warm.', 'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=200&q=80', 1, '2026-08-21 09:15:00'),
(4, 'Jordan M.', 5, 'Sofia cut my curls dry and for the first time in my life they behave. She sent me home with a two-minute routine and it actually works.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80', 1, '2026-08-05 14:45:00'),
(5, 'Ava L.', 5, 'Ines did my wedding hair — a low braided bun that survived an outdoor ceremony in Malibu and eleven hours of dancing. The trial was calm and genuinely fun.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=200&q=80', 1, '2026-07-18 12:00:00'),
(6, 'Meredith K.', 4, 'Beautiful space, thoughtful staff, excellent color. Only note is that parking on Abbot Kinney is a small adventure — leave ten extra minutes.', 'https://images.unsplash.com/photo-1615529182904-14819c35db37?auto=format&fit=crop&w=200&q=80', 1, '2026-07-02 11:20:00');

