INSERT OR IGNORE INTO blog_posts (id, title, slug, excerpt, content, cover_image, category, published_at) VALUES
(1, 'How to make a salon blow-dry last four days', 'make-a-blow-dry-last', 'The difference between a blow-dry that collapses overnight and one that holds until Thursday is almost entirely in the first ten minutes after you leave the chair.', '<p>Most blow-dries fail in the first night, not the fourth day. Hair holds the shape it dries in, and if you go to bed with warm hair pressed against a pillow, that is the shape you keep.</p><h2>1. Cool it down</h2><p>Before you leave the salon, ask for a cool-shot finish. Cool air closes the cuticle and sets the bend. At home, a thirty-second blast of cold air on dry hair revives the whole shape.</p><h2>2. Sleep on silk, loosely</h2><p>Gather hair into a loose high pony with a silk scrunchie, or use a silk pillowcase. Cotton grabs the cuticle and roughs up the ends — that is the fuzz you see on day two.</p><h2>3. Do not wet it down</h2><p>Water resets the style. For morning frizz, a pea-sized drop of lightweight oil on the ends, not the roots, and a two-minute cool blow-dry on the front section only.</p><h2>4. Wash less, rinse more</h2><p>If your scalp feels oily before your ends do, rinse with cool water and condition the ends only. It buys a day without stripping the style.</p>', 'https://images.unsplash.com/photo-1521590832167-7bcbfaa6381f?auto=format&fit=crop&w=1200&q=80', 'Care Tips', '2026-10-18'),
(2, 'The honest guide to going lighter without damage', 'going-lighter-without-damage', 'Two colorists on what actually happens in the chair when you ask for blonde, and how to plan for it.', '<p>Going lighter is a chemistry project with a social deadline. The clients who leave happiest are the ones who plan in appointments, not in shades.</p><h2>Start two shades away</h2><p>If your natural level is a 4 and you want a 9, expect two or three sessions. Each session lifts a little and protects a lot. Rushing it is how hair becomes straw.</p><h2>Ask for a bond builder, not a promise</h2><p>Bond-repair additives are not magic, but they measurably reduce breakage during lifting. Ask what is in the bowl and why.</p><h2>Gloss is your friend</h2><p>A gloss every six to eight weeks keeps tone clean between full appointments and costs a fraction of a lift.</p><h2>Book the trim</h2><p>Lightened hair needs dusting every eight weeks. A ten-minute trim protects the investment.</p>', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=1200&q=80', 'Color', '2026-09-29'),
(3, 'A curl routine that fits in five minutes', 'five-minute-curl-routine', 'Dry cutting, a microfiber towel and the right order of products — everything Sofia teaches at the chair.', '<p>Curly hair does not need more products. It needs the right order and a lot less touching.</p><h2>Wash, then squeeze</h2><p>Never rub. Squeeze water out with a microfiber towel until it stops dripping, then apply leave-in to soaking hair.</p><h2>Layer, do not pile</h2><p>Leave-in first, then a curl cream, then a light gel to cast the ends. Scrunch upward, once, and stop.</p><h2>Diffuse on low</h2><p>Hover, do not touch. Low heat, low speed, until eighty percent dry. Let the rest air-dry.</p><h2>Break the cast</h2><p>When fully dry, a drop of oil on the palms, scrunched upward. That is the whole routine.</p>', 'https://images.unsplash.com/photo-1521590832167-7bcbfaa6381f?auto=format&fit=crop&w=1200&q=80', 'Care Tips', '2026-09-12'),
(4, 'What to bring to your first appointment', 'first-appointment-guide', 'Photos, your routine, and the truth about how much time you actually spend on your hair. That is the whole list.', '<p>We ask three questions at every first appointment, and the answers change the cut more than any photo.</p><h2>How long do you actually style it?</h2><p>Two minutes and a claw clip is a different haircut from twenty minutes with a round brush. Both are good. They are not the same shape.</p><h2>What did you hate about your last cut?</h2><p>This is more useful than a reference image. Too heavy at the perimeter, too short in the fringe, too much thinning — it tells us what to avoid.</p><h2>Bring photos in your own hair texture</h2><p>A sleek bob on straight hair will not behave the same on 3B curls, but the shape can be adapted. Bring two: one for shape, one for feeling.</p>', 'https://images.unsplash.com/photo-1521590832167-7bcbfaa6381f?auto=format&fit=crop&w=1200&q=80', 'Salon Notes', '2026-08-30');

